    while x % k_val == 0:
        x //= k_val
    return x

def can_reduce_to_one(a, k, n):
    memo = {}

    def get_signature(nums):
        return tuple(sorted(nums))

    def dfs(current_nums, path):
        state = get_signature(current_nums)
        if state in memo:
            return memo[state]

        if len(current_nums) == 1:
            if current_nums[0] == 1:
                memo[state] = (True, list(path))
                return True
            memo[state] = (False, [])
            return False

        # Try all pairs
