            for j in range(i + 1, len(current_nums)):
                x = current_nums[i]
                y = current_nums[j]
                new_val = f(x + y, k)

                new_nums = current_nums[:i] + current_nums[i+1:j+1] 
                if i+1 > j+1:
                    new_nums = current_nums[:i] + [new_val]
                else:
                    new_nums = current_nums[:i] + [new_val] + current_nums[j+1:]

                # Better construction
