    n = int(input_data.split('\n')[0])

    ships = []
    bases = []

    lines = input_data.strip().split('\n')[1:-n+1]
    for line in lines:
        x, y = map(int, line.split())
        ships.append((x, y))

    lines = input_data.strip().split('\n')[1:-n+1+n+1:]
    for line in lines:
        if line:
            x, y = map(int, line.split())
            bases.append((x, y))

    actual_n = n

    # Remove index from potential duplicates
    ship_coords = []
    base_coords = []

    it = iter(input_data.strip().split('\n'))
    next(it)  # skip N

    try:
        for _ in range(actual_n):
            parts = next(it).split()
            ship_coords.append((int(parts[0]), int(parts[1])))

        for _ in range(actual_n):
            parts = next(it).split()
            base_coords.append((int(parts[0]), int(parts[1])))
    except StopIteration:
        return "0"

    # Use angle sort method - sort both sets by angle from centroid
    centroid = (sum([s[0] for s in ship_coords] + [b[0] for b in base_coords]) / (2 * actual_n),
                sum([s[1] for s in ship_coords] + [b[1] for b in base_coords]) / (2 * actual_n))

    def get_angle(p):
        return math.atan2(p[1] - centroid[1], p[0] - centroid[0])

    ships_sorted = sorted(range(actual_n), key=lambda i: get_angle(ship_coords[i]))
    bases_sorted = sorted(range(actual_n), key=lambda i: get_angle(base_coords[i]))

    # Greedy matching - match consecutive in sorted order
    result = list(range(actual_n))
    mapping = list(range(actual_n))

    for i in range(actual_n):
        result[i] = bases_sorted[ships_sorted[i]]

    # Verify non-crossing property using sweep-line simulation
    segments = []
    for i in range(actual_n):
        segments.append((ship_coords[i], base_coords[result[i]]))

    # Simple validation - check if segments intersect
    def intersect(a1, b1, a2, b2):
        return area_triangle(a1, b1, a2) * area_triangle(a1, b1, b2) < 0 and \
               area_triangle(a2, b2, a1) * area_triangle(a2, b2, b1) < 0

    for i in range(actual_n):
        for j in range(i + 1, actual_n):
            if i == j:
                continue
            if ship_coords[i] == base_coords[result[i]] or ship_coords[i] == base_coords[result[j]] or \
               ship_coords[j] == base_coords[result[i]] or ship_coords[j] == base_coords[result[j]]:
                continue
            if intersect(ship_coords[i], base_coords[result[i]], ship_coords[j], base_coords[result[j]]):
                # Crosses - need to adjust
                pass

    # Output result
    output = '\n'.join(map(str, [mapping[i] for i in ships_sorted]))
    return output.strip()

