def run_solution(input_str):
    n = int(input_str.split('\n')[0])

    coords = []
    lines = input_str.strip().split('\n')[1:]

    for line in lines[:n]:
        x, y = map(int, line.split())
        coords.append((x, y, 'S'))  # spaceship

    for line in lines[n:]:
        x, y = map(int, line.split())
        coords.append((x, y, 'B'))  # base

    # Sort all points by x then y
    coords.sort()

    result = []
    for i in range(n):
        if i % 2 == 0:
            result.append("S")
        else:
            result.append("B")

    # But we need to actual match S to B
    # Simple: connect all S to B in order if sorted by same metric

    # Since guaranteed solution exists, match based on angle from centroid
    cx = sum(c[0] for c in coords) / (2 * n)
    cy = sum(c[1] for c in coords) / (2 * n)

    def angle(p):
        return math.atan2(p[1] - cy, p[0] - cx)

    # Separate and sort
    ships = [c for c in coords[:n] if c[2] == 'S']
    bases = [c for c in coords[n:] if c[2] == 'B']

    ships_sorted = sorted(range(n), key=lambda i: angle((ships[i][0], ships[i][1])))
    bases_sorted = sorted(range(n), key=lambda i: angle((bases[i][0], bases[i][1])))

    # Match in sorted order
    mapping = [0] * n
    for i in range(n):
        mapping[ships_sorted[i]] = bases_sorted[i] + 1

    return '\n'.join(map(str, [mapping[i] for i in range(n)]))

