import sys
from collections import defaultdict, deque

def solution(input_string):
    lines = input_string.strip().split('\n')

    if len(lines) < 2:
        return "-1"

    first_line = lines[0].split()
    n = int(first_line[0])
    m = int(first_line[1])

    s, t = int(lines[1].split()[0]), int(lines[1].split()[1])

    edges = []
    for i in range(m):
        parts = lines[2 + i].split()
        edges.append({
            'id': i + 1,
            'u': int(parts[0]),
            'v': int(parts[1]),
            'w': int(parts[2])
        })

    def is_connected(mask=None):
        if mask is None:
            return False
        adj = defaultdict(list)
        for e in edges:
            if e['id'] not in mask:
                adj[e['u']].append(e['v'])
                adj[e['v']].append(e['u'])

        visited = set()
        q = [s]
        visited.add(s)
        idx = 0
        while idx < len(q):
            u = q[idx]
            idx += 1
            if u == t:
                return True
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    q.append(v)
        return t in visited

    # Case 0: Already disconnected
    if not edges:
        return "0\n0\n"

    # Case 1: Try removing 1 edge
    min_cost1 = float('inf')
    single_edge = None
    for e in edges:
        if is_connected({e['id']}):
            if e['w'] < min_cost1:
                min_cost1 = e['w']
                single_edge = e

    if single_edge:
        return f"{min_cost1}\n1\n{single_edge['id']}"

    # Case 2: Try removing 2 edges
    min_cost2 = float('inf')
    best_pair = None

    for i in range(m):
        # Early pruning
        if edges[i]['w'] >= min_cost2:
            continue
        for j in range(i + 1, m):
            if edges[i]['w'] + edges[j]['w'] >= min_cost2:
                break
            mask = {edges[i]['id'], edges[j]['id']}
            if not is_connected(mask):
                cost = edges[i]['w'] + edges[j]['w']
                if cost < min_cost2:
                    min_cost2 = cost
                    best_pair = (edges[i]['id'], edges[j]['id'])

    if best_pair:
        return f"{min_cost2}\n2\n{best_pair[0]} {best_pair[1]}"
    else:
        return "-1"

