import sys
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

    room_id = [[-1] * m for _ in range(n)]

    room_counter = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and room_id[r][c] == -1:
                min_r, max_r = r, r
                min_c, max_c = c, c
                queue = deque([(r, c)])
                room_id[r][c] = room_counter

                while queue:
                    cr, cc = queue.popleft()
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.' and room_id[nr][nc] == -1:
                            room_id[nr][nc] = room_counter
                            queue.append((nr, nc))
                            min_r = min(min_r, nr)
                            max_r = max(max_r, nr)
                            min_c = min(min_c, nc)
                            max_c = max(max_c, nc)

                # Fill the entire bounding box with free spaces
                for i in range(min_r, max_r + 1):
                    for j in range(min_c, max_c + 1):
                        grid[i][j] = '.'

                room_counter += 1

    return '\n'.join(''.join(row) for row in grid)

