        return 'NO\n'

    # Special case: k=0 means no N's at all
    if k == 0:
        if 'N' in s:
            return 'NO\n'
        return 'YES\n'

    # For k >= 1, we need to check if we can form exactly k consecutive N's
    # by examining '?' segments

    i = 0
    while i < n:
        if s[i] == '?':
            j = i
            while j < n and s[j] == '?':
                j += 1
            length = j - i

            # If this ? segment has length >= k, we can use it to form 
            # exactly k consecutive N's (the rest become Y's)
            if length >= k:
                return 'YES\n'

            i = j
        else:
            i += 1

    return 'NO\n'

