def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    p = list(map(int, lines[2].split()))
    m = int(lines[3])
    b = list(map(int, lines[4].split()))

    # Precompute positions for each value in a
    pos_map = {}
    for idx, val in enumerate(a):
        if val not in pos_map:
            pos_map[val] = []
        pos_map[val].append(idx)

    # Check if all required values exist
    for val in b:
        if val not in pos_map or not pos_map[val]:
            return "NO"

    # Precompute prefix_min_0: sum of min(0, p[i]) up to each position
    prefix_min_0 = [0] * (n + 1)
    for i in range(n):
        prefix_min_0[i+1] = prefix_min_0[i] + min(0, p[i])

    # Build Fenwick trees for efficient range queries
    # We need to query: sum of max(0, p[pos]) for positions in range and value >= threshold
    # Since values are 1..n, we can manage this with segment tree

    # Build arrays for the Fenwick tree
    costs_ge = [0] * (n + 1)  # costs_ge[v] = sum of max(0, p[i]) for a[i] = v
    for i in range(n):
        costs_ge[a[i]] = max(0, p[i])

    # Initialize Fenwick tree
    class FenwickTree:
        def __init__(self, arr):
            self.n = len(arr)
            self.tree = [0] * (self.n + 1)
            for i in range(self.n):
                self.update(i, arr[i])

        def update(self, idx, val):
            idx += 1  # 1-based indexing
            while idx < self.n + 1:
                self.tree[idx] += val
                idx += idx & -idx

        def query(self, idx):
            idx += 1
            result = 0
            while idx > 0:
                result += self.tree[idx]
                idx -= idx & -idx
            return result

        def range_query(self, l, r):
            if l > r:
                return 0
            return self.query(r) - self.query(l - 1)

    # We'll use dynamic programming
    # dp[i] = dictionary mapping position in a to min cost to match b[0..i]
    prev_dp = {}

    for i in range(m):
        target = b[i]
        target_cost = 0  # sum of costs for current matching

        curr_dp = {}

        # For each position where a[j] == b[i], compute possible costs
        positions = pos_map[target]

        for pos in positions:
            # Compute cost to reach this state
            base_cost = min(prefix_min_0[k] for k in prev_dp.keys()) if prev_dp else 0

            # Find the best previous position
            best_prev_cost = float('inf')
            best_k = None

            if i == 0:
                # First element: cost is from start to pos
                # All elements < pos with a[k] >= b[0] must be deleted
                prefix_cost = prefix_min_0[pos]
                # Add costs for a[k] >= target in range [0, pos)
                tree_cost = 0
                for k in range(pos):
                    if a[k] >= target:
                        tree_cost += max(0, p[k])
                curr_dp[pos] = prefix_cost + tree_cost
            else:
                # Try each previous position k where a[k] == b[i-1]
                if prev_dp:
                    prev_positions = sorted(prev_dp.keys())
                    best_k = None
                    best_k_cost = float('inf')

                    for k in prev_positions:
                        if k >= pos:
                            continue
                        if best_k_cost == float('inf'):
                            best_k_cost = prev_dp[k]
                            best_k = k
                            break

                        # Cost: dp[i-1][k] + (prefix_min_0[pos] - prefix_min_0[k]) + cost of a[k'<k] where a[k'] >= b[i]
                        interval_cost = prefix_min_0[pos] - prefix_min_0[k]
                        # Add costs for elements >= target in (k, pos)
                        ge_cost = 0
                        for k2 in range(k + 1, pos):
                            if a[k2] >= target:
                                ge_cost += max(0, p[k2])

                        total = prev_dp[k] + interval_cost + ge_cost
                        if total < best_k_cost:
                            best_k_cost = total
                            best_k = k

                    if i > 0 and best_k_cost == float('inf'):
                        # No valid previous match
                        continue

                    curr_dp[pos] = best_k_cost

        # Prepare for next iteration
        prev_dp = curr_dp
        if not prev_dp:
            return "NO"

    # Final answer is the minimum cost
    if prev_dp:
        return "YES\n" + str(min(prev_dp.values()))
    else:
        return "NO"

