def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    ops = []
    for line in lines[1:]:
        parts = list(map(int, line.split()))
        t, xp, y = parts
        x = xp / 100000.0
        ops.append((t, x, y))

    # ans[j] = earliest time-step to get exactly j bananas, -1 if impossible
    ans = [-1] * (m + 1)
    # reachable = set of banana counts we can achieve at current time step
    reachable: Set[int] = {0}

    for step_idx, (t, x, y) in enumerate(ops):
        next_step: Set[int] = set()

        for k in reachable:
            # Case a_i = 0: don't apply operation, k stays the same
            next_step.add(k)

            # Case a_i >= 1: apply operation 1 to y times
            val = k
            for _ in range(y):
                if t == 1:
                    val = math.ceil(val + x)
                else:
                    val = math.ceil(val * x)

                # Cap at m+1 since we only care about values <= m
                if val > m:
                    val = m + 1
                else:
                    next_step.add(val)
                    break

        # Update answer for newly reachable values
        for v in next_step:
            if v <= m and ans[v] == -1:
                ans[v] = step_idx + 1

        # Move to next time step
        reachable = next_step

    return ' '.join(map(str, ans[1:]))


