    elif n == 3:
        count = 0
        for b in range(l + 1, r):
            # c = b²/a must be in [l, r]
            # So a must be in [ceil(b²/r), floor(b²/l)]
            a_min = max(l, b * b // r)
            a_max = min(r, b * b // l)

            # a must be less than b (for distinctness in increasing seq)
            upper = min(a_max, b - 1)

            if a_min <= upper:
                for a in range(a_min, upper + 1):
                    if b * b % a == 0:
                        c = b * b // a
                        if l < a < b < c and c <= r:
                            count += 1
            return str(count * 2) + '\n'
    else:
        return "0\n"  # For n ≥ 4, typically no valid progressions in small ranges

import math
from typing import List, Tuple

def get_dist(p1: Tuple[int, int], p2: Tuple[int, int]) -> float:
    return math.hypot(p1[0] - p2[0], p1[1] - p2[1])

def check_collinear(circles: List[Tuple[int, int]]) -> bool:
    n = len(circles)
    if n < 3:
        return True  # Cannot form triangle

    def cross_product(p1, p2, p3):
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

    for i in range(3):
        if cross_product(circles[0], circles[1], circles[i]) == 0:
            continue

        for j in range(2, n - 2):
            for k in range(j + 1, n):
                if cross_product(circles[i], circles[j], circles[k]) != 0:
                    return False

    return True

def circumradius(a: float, b: float, c: float) -> float:
    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))
    return (a * b * c) / (4 * area)

