        cross = lambda x, y, z: (y[0] - x[0]) * (z[1] - x[1]) - (y[1] - x[1]) * (z[0] - x[0])
        for j in range(i + 2, n):
            if cross(circles[i], circles[i + 1], circles[j]) != 0:
                return True  # Found non-collinear triplet

    return False

