def solution(input_str):
    # Parse input safely
    lines = input_str.strip().split('\n')

    try:
        n = int(lines[0])
    except ValueError:
        return "NO\n"

    # Collect n strings, filtering empty ones
    strings = []
    for i in range(1, len(lines)):
        s = lines[i].strip()
        if s:
            strings.append(s)

    # Ensure we have exactly n strings or handle gracefully
    while len(strings) < n:
        strings.append("")

    # Check edge cases
    if n == 0 or not strings:
        return "NO\n"

    # Check if any string is a substring of another - if so, that string must appear more times
    # which creates constraints on character frequencies
    filtered_strings = []
    seen = set()
    for s in strings:
        is_sub = False
        for other in strings:
            if len(s) < len(other) and s in other or s == other:
                is_sub = True
                break
        if not is_sub:
            if s not in seen:
                filtered_strings.append(s)
                seen.add(s)

    if len(filtered_strings) != n:
        return "NO\n"

    # Check character frequency conflicts
    # If the same character appears in a conflict pattern, might be impossible
    char_freq_global = {}
    for s in filtered_strings:
        for c in s:
            char_freq_global[c] = char_freq_global.get(c, 0) + 1

    # Sort strings lexicographically
    filtered_strings.sort()

    return "".join(filtered_strings) + "\n"


