    all_prefixes = set()
    for s, _ in phone_numbers:
        for i in range(1, len(s) + 1):
            all_prefixes.add(s[:i])

    unique_prefixes = list(all_prefixes)

    if not unique_prefixes:
        total = sum(len(s) * m for s, m in phone_numbers)
        return str(total)

    # For each prefix, compute potential benefit (total length that would be saved)
    prefix_benefits = []
    for p in unique_prefixes:
        benefit = 0
        for s, m in phone_numbers:
            if s.startswith(p):
                benefit += (len(s) - len(p)) * m
        if benefit > 0:
            prefix_benefits.append((p, benefit))

    # Sort by benefit descending
    prefix_benefits.sort(key=lambda x: x[1], reverse=True)

    best_cost = None

    # Try all combinations of up to k prefixes
    for r in range(min(k + 1, len(prefix_benefits) + 1)):
        for selection in combinations(prefix_benefits, r):
            selected_prefixes = [x[0] for x in selection]
            # Compute actual cost with this selection
            total = 0
            for s, m in phone_numbers:
                best_len = 0
                for p in selected_prefixes:
