    import sys
    from itertools import combinations

    line = s.strip().split()
    if not line:
        return "0\n"
    n, m = int(line[0]), int(line[1])

    cells = [(r, c) for r in range(n) for c in range(m)]
    total = n * m

    if total == 1:
        return "0\n"

    def check(targets):
        """Check if the given target cells can receive all spiders"""
        covered = set()
        for (tr, tc) in targets:
            # A spider at position covered can move to (tr, tc)
            # This means position must be at Manhattan distance ≤ 1 from target
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    nr, nc = tr + dr, tc + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        covered.add((nr, nc))
        return len(covered) == total

    # Lower bound: each target covers at most 5 cells
    k_start = (total + 4) // 5

    # For small k values, search is manageable
    min_targets = total + 1
    found = False

    for k in range(k_start, min(total + 1, k_start + 300)):
        for combo in combinations(cells, k):
            if check(combo):
                min_targets = k
                found = True
                break
        if found:
            break

    if not found:
        min_targets = total

    return str(total - min_targets) + "\n"

