def solution(input_str):
    """
    Interactive game solver solution.
    Finds path from (1,1) to 'F' avoiding '*' cells.
    Returns sequence of moves as string.
    """
    lines = input_str.strip().split('\n')

    # Parse dimensions and swap flags
    first = lines[0].split()
    n, m = int(first[0]), int(first[1])

    len_first = len(first)
    swapLR = 1 if len_first > 2 else 0
    swapUD = 1 if len_first > 3 else 0

    # Parse grid
    grid = lines[1:1+n]

    # Find finish position
    finish = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                finish = (r + 1, c + 1)
                break
    if not finish:
        return ""

    # BFS navigation
    from collections import deque
    x, y = 1, 1
    visited = {(x, y)}
    queue = deque([(x, y, "")])

    # Direction mappings with swaps
    if swapLR:
        dir_map = {'U': (-1,0), 'D': (1,0), 'L': (0,1), 'R': (0,-1)}
    else:
        dir_map = {'U': (-1,0), 'D': (1,0), 'L': (0,-1), 'R': (0,1)}

    if swapUD:
        dir_map['U'] = (-1,0)
        dir_map['D'] = (1,0)

    while queue:
        cx, cy, path = queue.popleft()

        if (cx, cy) == finish:
            return path + "\n"

        for btn, (dr, dc) in dir_map.items():
            nx, ny = cx + dr, cy + dc

            # Out of bounds
            if nx < 1 or nx > n or ny < 1 or ny > m:
                continue

            # Dangerous cell
            if grid[nx-1][ny-1] == '*':
                continue

            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, path + btn))

    return "" + "\n"

