def try_find_paths(n, adj, s, t):
    """Try to find 3 internally disjoint paths using DFS"""
    if n < 2:
        return False

    def dfs(u, target, path, path_set, edge_blocked, path_count):
        if path_count[0] >= 3:
            return True

        if u == target:
            if len(path) > 1:  # Must have at least start and end
                paths.append(list(path))
                path_count[0] += 1
                if path_count[0] >= 3:
                    return True
                continue

        for v in adj[u]:
            edge_key = (u, v)
            if edge_blocked.get(edge_key, False):
                continue
            if len(path) >= 1 and v in path_set:
                continue  # Would create cycle or reuse internal node

            edge_blocked[(u, v)] = True
            edge_blocked[(v, u)] = True

            path.append(v)
            path_set.add(v)

            if dfs(v, target, path, path_set, edge_blocked, path_count):
                return True

            path.pop()
            path_set.remove(v)
            edge_blocked[(u, v)] = False
            edge_blocked[(v, u)] = False

    paths = []
    edge_blocked = {}
    path_count = [0]
    dfs(s, t, [s], {s}, edge_blocked, path_count)

    return len(paths) >= 3

def format_paths(n, adj, s, t):
    """Extract actual path strings"""
    # Find 3 vertices w1, w2, w3 that are neighbors of t (or s) and can form disjoint paths
    neighbors = [v for v in adj[t] if v != s]
    neighbors = neighbors[:3]  # Take up to 3

    paths = []
    for w in neighbors:
        path = find_simple_path(n, adj, s, w)
        if path:
            paths.append(path)
        else:
            paths.append([])

    paths.append(find_simple_path(n, adj, s, t))
    return [" ".join(map(str, p)) for p in paths[:3]]

def find_simple_path(n, adj, start, end):
    """Find a simple path from start to end"""
    if start == end:
        return [start]

    visited = {start}
    parent = {}
    queue = [start]

    while queue:
        u = queue.pop(0)
        if u == end:
            break

        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                parent[v] = u
                queue.append(v)

    if end not in parent or end not in visited:
        return []

    path = []
    node = end
    while node != start:
        path.append(node)
        node = parent[node]
    path.append(start)
    path.reverse()

    return path

