def solve_geometry(x1, y1, x2, y2, circles):
    """
    Find minimum radius circle passing through (x1,y1) and (x2,y2)
    that doesn't intersect any constraint circles (touching allowed, 
    circles can be inside constraint spheres).
    """
    midx = (x1 + x2) / 2
    midy = (y1 + y2) / 2

    dx = x2 - x1
    dy = y2 - y1
    dist_ab = math.hypot(dx, dy)

    # Perpendicular direction
    perp_x = -dy
    perp_y = dx

    if dist_ab > 0:
        len_ab = dist_ab
        ux = perp_x / len_ab
        uy = perp_y / len_ab
    else:
        ux, uy = 1, 0
        len_ab = 0

    def get_center(offset):
        return (midx + ux * offset, midy + uy * offset)

    def get_radius(cx, cy):
        return math.hypot(cx - x1, cy - y1)

    def is_valid(cx, cy, R):
        for (cxx, cyy, rc) in circles:
            d = math.hypot(cx - cxx, cy - cyy)
            # Two circles intersect if |R - rc| < d < R + rc
            # Valid if d >= R + rc (outside/touching) or d <= |R - rc| (inside/inside-touching)
            if not (d >= R + rc or d <= abs(R - rc)):
                return False
        return True

    # Binary search for minimum radius
    min_r = dist_ab / 2
    max_r = 1e18

    for _ in range(300):  # Enough iterations for precision
        mid_r = (min_r + max_r) / 2
        offset_sq = mid_r * mid_r - (dist_ab / 2) ** 2
        if offset_sq < 0:
            min_r = mid_r
            continue

        offset = math.sqrt(offset_sq)
        cx, cy = get_center(offset)

        if is_valid(cx, cy, mid_r):
            max_r = mid_r
        else:
            min_r = mid_r

    return max_r

