    cum_time = [0.0] * (len(P))
    for i in range(len(P) - 1):
        d = math.hypot(P[i+1][0]-P[i][0], P[i+1][1]-P[i][1], P[i+1][2]-P[i][2])
        cum_dist[i+1] = cum_dist[i] + d
        cum_time[i+1] = cum_dist[i+1] / vs

    best_t = float('inf')
    best_pos = None
    possible = False

