def solution(input_str):
    """
    Find a subset of employees such that when they attend the party,
    every employee receives a different number of messages than Igor predicted.
    """
    try:
        lines = input_str.strip().split('\n')
        n = int(lines[0])

        if n <= 0 or n > 100:
            return "-1\n"

        M = []
        for i in range(n):
            if i + 1 < len(lines):
                row = lines[i + 1]
                M.append([int(c) for c in row])
            else:
                M.append([0] * n)

        # Parse predictions on the last line
        a = []
        if n + 1 < len(lines):
            a = list(map(int, lines[n + 1].split()))
        else:
            return "-1\n"

        # Ensure predictions match n
        if len(a) != n:
            return "-1\n"

        # Try to find subset where ALL predictions are wrong
        result = find_subset(n, M, a)

        return result

    except Exception:
        return "-1\n"


def find_subset(n, M, a):
    """
    Find a subset of employees where actual messages ≠ predictions for all.
    """
    # Try subsets of increasing size
    for r in range(1, n + 1):
        from itertools import combinations
        for subset in combinations(range(n), r):
            subset_set = set(subset)
            # Calculate actual message counts
            actual = [0] * n
            for j in subset_set:
                for recipient in range(n):
                    if M[j][recipient] == 1:
                        actual[recipient] += 1
            # Check if all predictions are wrong
            if all(actual[i] != a[i] for i in range(n)):
                result_subset = [j + 1 for j in subset]  # Convert to 1-indexed
                return f"{len(result_subset)}\n{' '.join(map(str, result_subset))}\n"

    return "-1\n"


